        d("PM", "SPM", 0xFF101056, "ENTRÉE", "SAINT-PIERRE-ET-MIQUELON", AMERICAS),
        d("SX", "SXM", 0xFF891A23, "ENTRÉE", "SAINT-MARTIN", AMERICAS),
        d("GS", "SGS", 0xFF101056, "ENTRY", "SOUTH GEORGIA", PACIFIC),
        d("TC", "TCA", 0xFF102B56, "ENTRY", "TURKS AND CAICOS ISLANDS", AMERICAS),
        d("WF", "WLF", 0xFF101056, "ENTRÉE", "WALLIS ET FUTUNA", PACIFIC),
        d("EH", "ESH", 0xFF76161C, "ENTRADA", "SAHARA OCCIDENTAL", LEVANT),
        d("AX", "ALA", 0xFF103356, "INRESA", "ÅLAND", EUROPE),
    )

    /** Falls back to a neutral design rather than failing on an unknown code. */
    operator fun get(code: String): CountryTraits =
        byCode[code.uppercase()] ?: CountryTraits.unknown(code.uppercase())

    val all: Collection<CountryTraits> get() = byCode.values
}
